            "lang": "python",
            "label": "Python",
            "code": "import requests\nrequests.post(\"http://127.0.0.1:8090/naming/v1/circuitbreakers/releases\", json=[{\"id\":\"<rule-id>\",\"release_type\":\"normal\"}], headers={\"Authorization\": token})"
