          {
            "lang": "curl",
            "label": "cURL",
            "code": "curl -sS -X POST 'http://127.0.0.1:8090/naming/v1/traffic/security/delete' \\\n  -H \"Authorization: $TOKEN\" \\\n  -H 'Content-Type: application/json' \\\n  -d '[{\"id\":\"<rule-id>\"}]'"
          },
          {
            "lang": "javascript",
            "label": "JavaScript",
            "code": "await fetch('http://127.0.0.1:8090/naming/v1/traffic/security/delete', {\n  method: 'POST',\n  headers: {\n    Authorization: token,\n    'Content-Type': 'application/json',\n  },\n  body: JSON.stringify([{\"id\":\"<rule-id>\"}]),\n});"
          },
          {
            "lang": "go",
            "label": "Go",
            "code": "body := strings.NewReader(`[{\"id\":\"<rule-id>\"}]`)\nreq, _ := http.NewRequest(http.MethodPost, \"http://127.0.0.1:8090/naming/v1/traffic/security/delete\", body)\nreq.Header.Set(\"Authorization\", token)\nreq.Header.Set(\"Content-Type\", \"application/json\")\nresp, err := http.DefaultClient.Do(req)"
          },
          {
            "lang": "python",
            "label": "Python",
            "code": "import requests\nrequests.post(\"http://127.0.0.1:8090/naming/v1/traffic/security/delete\", json=[{\"id\":\"<rule-id>\"}], headers={\"Authorization\": token})"
          }
